    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HostPlatform {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .android
        
        case 2: return .ios
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

